using System;using System.IO;using System.Linq;using System.Threading;using System.Diagnostics;using System.Drawing;using System.Reflection;using System.Text;using System.Runtime.InteropServices;using System.Windows.Forms;using LcPack;
class RunningGameTests {
 delegate bool EnumProc(IntPtr h,IntPtr p);[DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr h,EnumProc cb,IntPtr p);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder s,int n);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
 static int passed;static void Check(bool b,string n){if(!b)throw new Exception(n);Console.WriteLine("PASS "+(++passed)+" "+n);}static void Reject(Action a,string n){try{a();}catch(IOException){Check(true,n);return;}throw new Exception("accepted: "+n);}
 [STAThread]static void Main(string[] args){Process runtime=null;try{Application.EnableVisualStyles();string candidate=Path.GetFullPath(args[0]),actualRoot=Path.GetFullPath(args[1]),evidence=Path.GetFullPath(args[2]);Check(Process.GetProcessesByName("Lethal Company").Any(p=>String.Equals(p.MainModule.FileName,Path.Combine(actualRoot,"Lethal Company.exe"),StringComparison.OrdinalIgnoreCase)),"real isolated V81 game process active");
 string root=Path.Combine(Path.GetTempPath(),"lgp-running-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"Lethal Company_Data/Managed"));foreach(string file in new[]{"Lethal Company.exe","UnityPlayer.dll","Lethal Company_Data/Managed/Assembly-CSharp.dll"})File.WriteAllText(Path.Combine(root,file),"fixture");File.Copy(candidate,Path.Combine(root,Channel.ClientName));var before=Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(f=>f,Data.Hash);
 using(var launcher=Process.Start(new ProcessStartInfo(Path.Combine(root,Channel.ClientName)){UseShellExecute=false,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=root})){Check(launcher.WaitForExit(15000)&&launcher.ExitCode==0,"normal double-click entry bootstraps while real game running");}
 var release=SelfUpdate.State(root).active;Check(release!=null&&release.version=="1.14.0.0","verified cache activation selects 1.14.0.0");string exe=SelfUpdate.CachedExe(root,release);for(int i=0;i<100&&runtime==null;i++){foreach(var p in Process.GetProcessesByName("client")){if(String.Equals(p.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase)&&p.MainWindowHandle!=IntPtr.Zero){runtime=p;break;}p.Dispose();}if(runtime==null)Thread.Sleep(100);}Check(runtime!=null,"actual receiver main window is open");var texts=new StringBuilder();for(int attempt=0;attempt<100;attempt++){texts.Clear();EnumChildWindows(runtime.MainWindowHandle,(h,p)=>{var s=new StringBuilder(1000);GetWindowText(h,s,1000);texts.AppendLine(s.ToString());return true;},IntPtr.Zero);if(texts.ToString().Contains("浏览模式"))break;Thread.Sleep(50);}File.WriteAllText(Path.Combine(evidence,"running-window-controls.txt"),texts.ToString());Check(texts.ToString().Contains("浏览模式")&&texts.ToString().Contains("故障诊断")&&texts.ToString().Contains("退出游戏后检查更新"),"real window exposes diagnostics and read-only browsing mode");
 Reject(Engine.CheckGameStopped,"game file guard remains active");Reject(()=>DiagnosticsStore.Install(root),"plugin overwrite blocked");Reject(()=>DiagnosticsStore.Configure(root,false,"F9"),"plugin enable/hotkey changes blocked");Reject(()=>SelfUpdate.RefreshLegacyLauncher(root).GetAwaiter().GetResult(),"launcher replacement blocked during game");using(var transfer=new Transfer()){Reject(()=>SelfUpdate.Check(root,transfer,(s,p)=>{}).GetAwaiter().GetResult(),"receiver install update blocked during game");Reject(()=>new Engine(root,Engine.CheckGameStopped).Run(transfer,(s,p)=>{}).GetAwaiter().GetResult(),"ordinary MOD update blocked before network or mutation");}
 Check(before.All(p=>Data.Hash(p.Key)==p.Value)&&Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length==before.Count,"opening receiver and rejected operations leave game directory byte-for-byte unchanged");
 var live=DiagnosticsStore.Sessions(actualRoot).First(s=>DiagnosticsStore.Active(s.Path));string heartbeat=Path.Combine(live.Path,"heartbeat.json");var beforeHeartbeat=File.GetLastWriteTimeUtc(heartbeat);using(var w=new DiagnosticsWindow(actualRoot)){w.Opacity=0;w.ShowInTaskbar=false;w.Show();Application.DoEvents();var sessionList=(ListBox)typeof(DiagnosticsWindow).GetField("sessions",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);Check(sessionList.Items.Count>0,"diagnostic UI reads real current and historical sessions");var save=(Button)typeof(DiagnosticsWindow).GetField("save",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);var export=(Button)typeof(DiagnosticsWindow).GetField("export",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);Check(!save.Enabled&&!export.Enabled,"real live session cannot be edited or exported");using(var image=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(evidence,"live-session.png"));}w.Close();}
 Thread.Sleep(2300);Check(File.GetLastWriteTimeUtc(heartbeat)>beforeHeartbeat&&DiagnosticsStore.Active(live.Path),"independent plugin keeps writing while receiver opens and closes");PostMessage(runtime.MainWindowHandle,0x10,IntPtr.Zero,IntPtr.Zero);Check(runtime.WaitForExit(5000),"read-only receiver closes normally without closing game");Console.WriteLine("RESULT "+passed+" actual-game checks; fixture "+root);
 }catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}finally{if(runtime!=null){if(!runtime.HasExited)PostMessage(runtime.MainWindowHandle,0x10,IntPtr.Zero,IntPtr.Zero);runtime.Dispose();}}}
}
